import * as React from "react"
import { addPropertyControls, ControlType } from "framer"

/**
 * Casper — Portfolio Case Study (Framer code component)
 *
 * Case study anonimizzato: nessun riferimento al cliente originale.
 * "Casper" è il nome del concept di AI Home Agent ideato dal team
 * durante una sfida di 4 giorni al Master in UX/UI Design — Talent Garden.
 * Il panel qualitativo citato nel case study è sintetico (costruito su
 * brief e desk research), non ricerca primaria diretta con utenti reali.
 *
 * Tutti gli screenshot/video delle 4 soluzioni e i mockup della hero
 * si caricano dal pannello proprietà di Framer (nessun asset binario
 * incorporato nel codice, a eccezione del logo Talent Garden — piccolo
 * a sufficienza da poter stare come default già pronto).
 */

type Props = {
    variant: "Desktop" | "Tablet" | "Mobile"
    enableAnimations: boolean
    videoDelayMs: number
    typeScale: number
    bodyScale: number
    backgroundColor: string
    textColor: string
    accentColor: string
    masterLogo: string
    imageHero: string
    imageHeroBack: string
    videoUrl: string
    imageDashboard: string
    videoDashboard: string
    imageLearning: string
    videoLearning: string
    imageOffline: string
    videoOffline: string
    imageWidget: string
    videoWidget: string
    protoUrl: string
    protoQr: string
}

// Logo Talent Garden (Master in UX/UI Design) — estratto dal deck originale,
// già anonimizzato: nessun logo del cliente è incorporato in questo file.
const MASTER_LOGO_DEFAULT =
    "data:image/png;base64,"

function mediaTile(
    image: string,
    video: string,
    alt: string,
    placeholderLabel: string,
    placeholderTitle: string
) {
    if (video) {
        return `
<div class="media-shot">
  <video class="media-video" src="${video}" ${image ? `poster="${image}"` : ""} muted loop playsinline preload="metadata" data-autoplay-video></video>
</div>`
    }
    if (image) {
        return `
<div class="media-shot">
  <img class="mockup-img" src="${image}" alt="${alt}" loading="lazy" decoding="async">
</div>`
    }
    return `
<div class="media-shot">
  <div class="mockup-placeholder">
    <span>${placeholderLabel}</span>
    <b>${placeholderTitle}</b>
    <small>Carica screenshot o video da "assets/solutions/" nel pannello Framer</small>
  </div>
</div>`
}

